composition "Model Village Deterministic Behavior" {
  state {
    water: 2
    privateAdapter: "fixture-private-adapter"
  }

  logic {
    action observe(residentId) {
      return {
        resident_id: residentId,
        location: "commons",
        visible_event_ids: [],
